"""Digital.ai platform-report keywords for Robot Framework + AppiumLibrary (generated by the Digital.ai Testing MCP).

seetest:client commands take their arguments as separate execute_script parameters — the inline form
("seetest:client.report('x')") is not reliable. Appium Server sessions only.
"""
from robot.libraries.BuiltIn import BuiltIn


class DigitalAiReport:
    ROBOT_LIBRARY_SCOPE = 'TEST'

    def __init__(self):
        self._group_open = False

    def _driver(self):
        return BuiltIn().get_library_instance('AppiumLibrary')._current_application()

    def start_steps_group(self, name):
        """Open a named steps group in the platform report."""
        self._driver().execute_script('seetest:client.startStepsGroup', name)
        self._group_open = True

    def stop_steps_group(self):
        """Close the open steps group (no-op when none is open)."""
        if self._group_open:
            self._driver().execute_script('seetest:client.stopStepsGroup')
            self._group_open = False

    def report_step(self, message, passed=True):
        """Add a step to the platform report."""
        self._driver().execute_script('seetest:client.report', message, 'true' if passed else 'false')

    def report_test_outcome(self, status, message=''):
        """Set the platform report status from Robot's ${TEST STATUS}: PASS → Passed, SKIP → Skipped, else Failed."""
        mapped = {'PASS': 'Passed', 'SKIP': 'Skipped'}.get(str(status).upper(), 'Failed')
        self._driver().execute_script('seetest:client.setReportStatus', mapped, (message or 'All steps completed')[:500])
